    func testAll45TablesMatchOriginalPNGAndCUBEGridSamplesAndManagedP3Input() throws {
        XCTAssertEqual(ImportedFilterCatalog.entries.count, 45)
        XCTAssertEqual(Set(FilmStyle.availableStyles).count, 46)
        for entry in ImportedFilterCatalog.entries { XCTAssertNotNil(ImportedFilterCatalog.table(entry)?.data, entry.title) }
        let samples = try JSONDecoder().decode([Sample].self, from: Data(fixture.utf8))
        let sRGB = CGColorSpace(name: CGColorSpace.sRGB)!, p3 = CGColorSpace(name: CGColorSpace.displayP3)!
        let context = CIContext(options: [.cacheIntermediates: false])
        for sample in samples {
            let style = try XCTUnwrap(FilmStyle(rawValue: sample.style))
            for wide in [false, true] {
                let original = try XCTUnwrap(CGColor(colorSpace: sRGB, components: sample.rgb + [1]))
                let color = wide ? try XCTUnwrap(original.converted(to: p3, intent: .relativeColorimetric, options: nil)) : original
                let input = CIImage(color: CIColor(cgColor: color)).cropped(to: CGRect(x: 0,y: 0,width: 4,height: 4))
                let result = ImportedFilterCatalog.apply(try XCTUnwrap(ImportedFilterCatalog.definition(for: style)), to: input)
                var pixels = [UInt8](repeating: 0,count: 4)
                pixels.withUnsafeMutableBytes { context.render(result, toBitmap: $0.baseAddress!, rowBytes: 4, bounds: CGRect(x:0,y:0,width:1,height:1),format:.RGBA8,colorSpace:sRGB) }
                for channel in 0..<3 {
                    let expected = min(max(sample.expected[channel],0),1) * 255
                    XCTAssertEqual(CGFloat(pixels[channel]), expected, accuracy: 3, "\(style.title) P3=\(wide) sample=\(sample.rgb)")
                }
                XCTAssertEqual(pixels[3],255)
            }
        }
    }
    func testAllImportedTablesInterpolateOffGridAndBlendInManagedColorSpaces() throws {
        let sRGB = CGColorSpace(name: CGColorSpace.sRGB)!, p3 = CGColorSpace(name: CGColorSpace.displayP3)!
        let context = CIContext(options: [.cacheIntermediates: false])
        func linear(_ v: Double) -> Double { v <= 0.04045 ? v / 12.92 : pow((v + 0.055) / 1.055, 2.4) }
        func encoded(_ v: Double) -> Double { v <= 0.0031308 ? v * 12.92 : 1.055 * pow(v, 1 / 2.4) - 0.055 }
        var seed: UInt64 = 932671
        func random() -> Double {
            seed = seed &* 6364136223846793005 &+ 1
            return Double((seed >> 32) & 0xffffff) / Double(0xffffff)
        }
        for entry in ImportedFilterCatalog.entries { try autoreleasepool {
            let lut = try XCTUnwrap(ImportedFilterCatalog.table(entry))
            let floats = try XCTUnwrap(lut.data).withUnsafeBytes { Array($0.bindMemory(to: Float.self)) }
            let n = lut.dimension
            for _ in 0..<32 { try autoreleasepool {
                let rgb = [random(), random(), random()]
                let coordinates = rgb.map { $0 * Double(n - 1) }
                let lower = coordinates.map { Int(floor($0)) }
                let fraction = zip(coordinates, lower).map { $0 - Double($1) }
                var expected = [Double](repeating: 0, count: 3)
                for b in 0...1 { for g in 0...1 { for r in 0...1 {
                    let index = ((min(lower[2]+b,n-1)*n + min(lower[1]+g,n-1))*n + min(lower[0]+r,n-1))*4
                    let weight = (r == 0 ? 1-fraction[0] : fraction[0]) * (g == 0 ? 1-fraction[1] : fraction[1]) * (b == 0 ? 1-fraction[2] : fraction[2])
                    for c in 0..<3 { expected[c] += Double(floats[index+c]) * weight }
                } } }
                let components: [CGFloat] = rgb.map { CGFloat($0) } + [CGFloat(1)]
                let color = try XCTUnwrap(CGColor(colorSpace: sRGB, components: components))
                for wide in [false, true] {
                    let managed = wide ? try XCTUnwrap(color.converted(to: p3, intent: .relativeColorimetric, options: nil)) : color
                    let image = CIImage(color: CIColor(cgColor: managed)).cropped(to: CGRect(x:0,y:0,width:2,height:2))
                    for intensity in [0.0,0.5,1.0] {
                        let strength = FilmStyle.effectStrength(for: intensity)
                        let result = entry.style.apply(to: image, intensity: intensity)
                        var pixels = [UInt8](repeating:0,count:4)
                        pixels.withUnsafeMutableBytes { context.render(result,toBitmap:$0.baseAddress!,rowBytes:4,bounds:CGRect(x:0,y:0,width:1,height:1),format:.RGBA8,colorSpace:sRGB) }
                        for c in 0..<3 {
                            var mapped = expected.map(linear)
                            if entry.style == .lut64f854a875 {
                                let v = mapped
                                mapped = [v[0]*0.8705014051+v[1]*0.1273577982+v[2]*0.0234525729,
                                          v[0]*0.0075246332+v[1]*0.9832630517+v[2]*0.0380165335,
                                          v[0]*0.1015841025-v[1]*0.1034520963+v[2]*1.0677660505]
                            }
                            let target = encoded(mapped[c] * strength + linear(rgb[c]) * (1-strength))
                            XCTAssertEqual(Double(pixels[c]),min(max(target,0),1)*255,accuracy:3,"\(entry.title) P3=\(wide) strength=\(strength) input=\(rgb)")
                        }
                    }
                }
            } }
        } }
    }
    @MainActor func testEveryImportedFilterRetainsIndependentEditsAndFavorites() throws {
        let name = "ImportedFilters-" + UUID().uuidString
        let defaults = try XCTUnwrap(UserDefaults(suiteName: name))
        defer { defaults.removePersistentDomain(forName: name) }
        let store = FilterSettingsStore(defaults: defaults)
        for (index, style) in FilmStyle.availableStyles.enumerated() {
            var recipe = FilterAdjustments(); recipe[.temperature] = Double(index)-20
            store.set(SavedFilterSettings(intensity:0.75,adjustments:recipe),for:style)
        }
        store.flush()
        let reopened = FilterSettingsStore(defaults: defaults)
        for (index, style) in FilmStyle.availableStyles.enumerated() { XCTAssertEqual(reopened.settings(for:style).adjustments[.temperature],Double(index)-20,style.title) }
        let picker = FilterPickerViewModel(defaults: defaults)
        for style in FilmStyle.availableStyles.dropFirst() { picker.toggleFavorite(style) }
        let restored = FilterPickerViewModel(defaults: defaults); restored.category = .favorites
        XCTAssertEqual(restored.styles,Array(FilmStyle.availableStyles.dropFirst()))
    }
}
